The quadrilateral has $AB=CD=7\text{ cm}$ and $AD=CB=4\text{ cm}$. Prove that $\Delta ABD\equiv\Delta CDB$, and hence that $AD\parallel BC$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,2);\coordinate (B) at (3.5,2);\coordinate (C) at (4.5,0);\coordinate (D) at (1,0);
\draw (A)--(B)--(C)--(D)--cycle (B)--(D);
\path (A) node[above left] {$A$} (B) node[above right] {$B$} (C) node[below right] {$C$} (D) node[below left] {$D$};
\path (1.75,2) node[above] {$7\text{ cm}$} (2.75,0) node[below] {$7\text{ cm}$} (0.5,1) node[left] {$4\text{ cm}$} (4,1) node[right] {$4\text{ cm}$};
\end{tikzpicture}
[/tikz]

$AC$ and $DB$ intersect at $E$. Given $AE=CE=5\text{ cm}$ and $DE=BE=3\text{ cm}$, prove that $\Delta AED\equiv\Delta CEB$. Hence prove that $\angle EAD=\angle ECB$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (E) at (0,0);\coordinate (A) at (-2,1);\coordinate (C) at (2,-1);\coordinate (D) at (-1.2,-0.8);\coordinate (B) at (1.2,0.8);
\draw (A)--(C) (D)--(B) (A)--(D) (C)--(B);
\path (A) node[above left] {$A$} (C) node[below right] {$C$} (D) node[below left] {$D$} (B) node[above right] {$B$} (E) node[above] {$E$};
\path (-1,0.5) node[above left] {$5\text{ cm}$} (1,-0.5) node[below right] {$5\text{ cm}$} (-0.6,-0.4) node[below] {$3\text{ cm}$} (0.6,0.4) node[above right] {$3\text{ cm}$};
\end{tikzpicture}
[/tikz]

$AE$ and $BD$ intersect at $C$, with $AB\parallel DE$ and $BC=DC=4\text{ cm}$. Prove that $\Delta ABC\equiv\Delta EDC$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (C) at (0,0);\coordinate (A) at (-2,1);\coordinate (E) at (2,-1);\coordinate (B) at (-1.5,-1);\coordinate (D) at (1.5,1);
\draw (A)--(E) (B)--(D) (A)--(B) (D)--(E);
\draw[->] (-1.82,0.28)--(-1.73,-0.08);\draw[->] (1.68,0.28)--(1.77,-0.08);
\path (A) node[above left] {$A$} (B) node[below left] {$B$} (D) node[above right] {$D$} (E) node[below right] {$E$} (C) node[above] {$C$};
\path (-0.75,-0.5) node[below] {$4\text{ cm}$} (0.75,0.5) node[above] {$4\text{ cm}$};
\end{tikzpicture}
[/tikz]

$PQ=PR=10\text{ cm}$, $S$ lies on $QR$, and $PS\perp QR$. Prove that $\Delta PSQ\equiv\Delta PSR$, and hence that $S$ is the midpoint of $QR$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (0,3);\coordinate (Q) at (-1.8,0);\coordinate (R) at (1.8,0);\coordinate (S) at (0,0);
\draw (P)--(Q)--(R)--cycle (P)--(S);\draw (0.25,0)--(0.25,0.25)--(0,0.25);
\path (P) node[above] {$P$} (Q) node[below left] {$Q$} (R) node[below right] {$R$} (S) node[below] {$S$};
\path (-0.9,1.5) node[left] {$10\text{ cm}$} (0.9,1.5) node[right] {$10\text{ cm}$};
\end{tikzpicture}
[/tikz]

$O$ is the centre of a circle of radius $3\text{ cm}$. $AD$ and $BC$ are diameters. Prove that $\Delta AOB\equiv\Delta DOC$, and hence that $AB\parallel CD$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0);\coordinate (A) at (-1.732,1);\coordinate (D) at (1.732,-1);\coordinate (B) at (0,2);\coordinate (C) at (0,-2);
\draw (O) circle (2);\draw (A)--(D) (B)--(C) (A)--(B) (D)--(C);\fill[black] (O) circle (1.2pt);
\path (O) node[below left] {$O$} (A) node[left] {$A$} (B) node[above] {$B$} (C) node[below] {$C$} (D) node[right] {$D$};
\end{tikzpicture}
[/tikz]

$O$ is the centre of the circle. $D$ is the midpoint of chord $AB$, with $AD=DB=2\text{ cm}$. Use congruent triangles to prove that $OD\perp AB$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0);\coordinate (A) at (-1.6,-1.2);\coordinate (B) at (1.6,-1.2);\coordinate (D) at (0,-1.2);
\draw (O) circle (2);\draw (O)--(A)--(B)--(O) (O)--(D);\fill[black] (O) circle (1.2pt);
\path (O) node[above] {$O$} (A) node[below left] {$A$} (B) node[below right] {$B$} (D) node[below] {$D$};
\path (-0.8,-1.2) node[below] {$2\text{ cm}$} (0.8,-1.2) node[below] {$2\text{ cm}$};
\end{tikzpicture}
[/tikz]

$A$, $B$ and $C$ lie on a straight line, $BD\perp AC$, and $\angle ADB=\angle CDB=35^\circ$. Prove that $\Delta ABD\equiv\Delta CBD$, and hence that $\Delta ACD$ is isosceles.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (-1.68,0);\coordinate (B) at (0,0);\coordinate (C) at (1.68,0);\coordinate (D) at (0,2.4);
\draw (A)--(C)--(D)--cycle (D)--(B);\draw (0.25,0)--(0.25,0.25)--(0,0.25);
\path (A) node[below left] {$A$} (B) node[below] {$B$} (C) node[below right] {$C$} (D) node[above] {$D$};
\path (-0.38,1.55) node {$35^\circ$} (0.38,1.55) node {$35^\circ$};
\end{tikzpicture}
[/tikz]

$AB=AD=3\text{ cm}$ and $\angle ABC=\angle ADC=90^\circ$. Prove that $\Delta ABC\equiv\Delta ADC$, and hence that $AC$ bisects $\angle BAD$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);\coordinate (B) at (1,1.732);\coordinate (C) at (4,0);\coordinate (D) at (1,-1.732);
\draw (A)--(B)--(C)--(D)--cycle (A)--(C);
\coordinate (b1) at ($(B)!0.25cm!(A)$);\coordinate (b2) at ($(B)!0.25cm!(C)$);\draw (b1)--($(b1)+(b2)-(B)$)--(b2);
\coordinate (d1) at ($(D)!0.25cm!(A)$);\coordinate (d2) at ($(D)!0.25cm!(C)$);\draw (d1)--($(d1)+(d2)-(D)$)--(d2);
\path (A) node[left] {$A$} (B) node[above] {$B$} (C) node[right] {$C$} (D) node[below] {$D$};
\path (0.5,0.866) node[left] {$3\text{ cm}$} (0.5,-0.866) node[left] {$3\text{ cm}$};
\end{tikzpicture}
[/tikz]
